import static org.jsoup.helper.DataUtil.UTF_8;
import org.jsoup.helper.UrlBuilder;
import org.junit.Test;
import java.io.UnsupportedEncodingException;
import java.net.MalformedURLException;
import java.net.URL;
import org.junit.Assert;

public class UrlBuilderTest {

    @Test
    public void buildTest() throws MalformedURLException {
        URL inputUrl = new URL("http://www.example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        URL actualUrl = urlBuilder.build();
        Assert.assertEquals(inputUrl, actualUrl);
    }

    @Test
    public void appendKeyValTest() throws UnsupportedEncodingException {
        URL inputUrl = new URL("http://www.example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        urlBuilder.appendKeyVal(new Connection.KeyVal("key", "value", true));
        Assert.assertEquals("http://www.example.com?key=value", urlBuilder.toString());
    }

}
```

This code has 2 test cases:

* `buildTest` - Checks if the `build` method returns the expected URL.
* `appendKeyValTest` - Checks if the `appendKeyVal` method appends the key-value pair correctly to the URL.
